export type RegulatoryFramework = 'fda_510k' | 'fda_pma' | 'eu_mdr' | 'ich_clinical' | 'cer_clinical_evaluation' | 'general_regulatory';

export interface DocumentDraftRequest {
  /** Backend-loaded project evidence; never copied from tool arguments. */
  sourceContext?: import('./draft-project-sources.js').DraftSourceContext;
  /** Regulatory framework context */
  framework: RegulatoryFramework;
  /**
   * Canonical submission/filing type (any of the 158+ registry IDs or aliases,
   * e.g. 'US_IND', 'CA_NDS', 'JP_MKT_APPROVAL', '510k'). When provided, the
   * system prompt is resolved from the Global Document Registry via the bridge,
   * unlocking framework-grade authoring for ALL filing types — not just the six
   * hardcoded frameworks. Falls back to `framework` when absent/unrecognized.
   */
  submissionType?: string;
  /** Document section or type to draft */
  sectionType: string;
  /** User instructions / content requirements */
  instructions: string;
  /** Optional existing content to revise */
  existingContent?: string;
  /** Project context (device type, indication, etc.) */
  projectContext?: {
    deviceName?: string;
    deviceType?: string;
    indication?: string;
    predicateDevice?: string;
    classification?: string;
    /** Caller-declared context, not independently qualified project evidence. */
    therapeuticArea?: string;
    modality?: string;
  };
  /** Enable extended thinking for complex analysis */
  enableThinking?: boolean;
  /** Thinking budget tokens (default: 10000) */
  thinkingBudget?: number;
  /** Enable agentic tool use */
  enableTools?: boolean;
  /** Streaming callback */
  onStream?: StreamCallback;
  /** Organization/user context for audit */
  organizationId?: string | number;
  userId?: string | number;
  projectId?: string | number;
}

export interface DocumentDraftResponse {
  /** Generated document content */
  content: string;
  /** Extended thinking output (reasoning chain) */
  thinking?: string;
  /** Tools invoked during generation */
  toolsUsed?: string[];
  /** Provider and model info */
  model: string;
  /** Token usage */
  usage: {
    inputTokens: number;
    outputTokens: number;
    estimatedCostUsd: number;
  };
  /** Whether prompt cache was hit (cost savings) */
  cacheHit?: boolean;
  /** Latency in ms */
  latencyMs: number;
  /**
   * Why generation ended, verbatim from the provider — 'end_turn',
   * 'max_tokens', 'length', 'chunk_timeout', 'unknown'. The gateway has always
   * recorded this and this service used to drop it, so a narrative that hit the
   * 8192-token ceiling mid-sentence came back indistinguishable from a finished
   * one and could be accepted into `coauthor_documents`, which is the table
   * eCTD leaves are materialized from.
   */
  finishReason?: string;
  /**
   * True when {@link finishReason} says the output was cut off with more to
   * say. Required, not optional, so the compiler catches a return site that
   * drops the signal. Not the negation of "complete": an absent or unknown
   * reason is neither, and a governed write should treat not-knowing as
   * not-confirmed.
   */
  truncated: boolean;
}

function modalityDraftAdvisory(modality: ReturnType<typeof normalizeModality>, section: string | null) {
  if (!modality) return ['PRODUCT MODALITY: UNASSESSED. No unambiguous modality was supplied; do not sharpen a broad biologic label.'];
  const blocks = [`PRODUCT MODALITY (declared): ${MODALITY_LABEL[modality]}.`];
  if (section?.startsWith('3.')) {
    blocks.push(`Existing modality CMC reference set (advisory, currency unverified): ${MODALITY_FRAME[modality].cmcCore.join('; ')}.`);
    blocks.push('Assess each reference against the actual product and development phase. Missing characterization, validation or comparability results remain evidence gaps, never invented results.');
  }
  return blocks;
}

/** Carry declared product context into the nested draft; do not promote it to evidence. */
function draftProductAdvisory(
  context: DocumentDraftRequest['projectContext'], sectionType: string, requirementsSource: string,
) {
  const profile = getProfile(typeof context?.therapeuticArea === 'string' ? context.therapeuticArea : null);
  const modality = normalizeModality(typeof context?.modality === 'string' ? context.modality : null);
  const audit = { productContextSource: 'caller-declared-unverified', therapeuticProfile: profile?.id ?? null, productModality: modality };
  if (!context || (context.therapeuticArea === undefined && context.modality === undefined)) {
    return { prompt: '', audit: { ...audit, productContextSource: 'unassessed' } };
  }
  const section = leadingSectionCode(sectionType)?.code ??
    /^record:ctd-section:([^:]+):/.exec(requirementsSource)?.[1] ?? null;
  const blocks = [
    'PRODUCT CONTEXT STATUS: CALLER-DECLARED, UNVERIFIED ADVISORY.',
    'These labels select existing advisory context; they are not server-loaded project facts or scientific source qualification. ' +
      'Use the selected section requirements and supplied evidence first. Confirm phase, disease stage, population and product details; ' +
      'do not infer modality from therapeutic area, or an approved pathway from a profile. Static reference titles do not establish current guidance status or effective dates.',
  ];
  blocks.push(profile
    ? renderProfileForPrompt(profile, { activeCtdSection: section, onlyApplicableRules: true, maxBulletsPerSection: 4 })
    : 'THERAPEUTIC AREA: UNASSESSED. No recognized area label was supplied; do not substitute another profile.');
  blocks.push(...modalityDraftAdvisory(modality, section));
  return { prompt: `${blocks.join('\n')}\n\n`, audit };
}

export interface VisionAnalysisRequest {
  /** Base64-encoded image data */
  imageData: string;
  /** Image MIME type */
  mediaType: 'image/jpeg' | 'image/png' | 'image/gif' | 'image/webp';
  /** Analysis instructions */
  instructions: string;
  /** Regulatory framework for context */
  framework?: RegulatoryFramework;
  /** Canonical submission/filing type — registry-driven prompt for any of 158+ types. */
  submissionType?: string;
  /** Enable extended thinking */
  enableThinking?: boolean;
  /** Streaming callback */
  onStream?: StreamCallback;
  organizationId?: string | number;
  userId?: string | number;
}

export interface BatchDocumentRequest {
  /** Array of draft requests to process */
  requests: DocumentDraftRequest[];
  /** Positive integer; defaults to 3 and is capped at 5. */
  concurrency?: number;
}

/** Pin caller-owned scalar fields and declared product context before awaits.
 * The selected-source object itself must retain its private issuer identity. */
function snapshotDraftRequest(request: DocumentDraftRequest): DocumentDraftRequest {
  const pinned = { ...request };
  if (pinned.projectContext) pinned.projectContext = Object.freeze({ ...pinned.projectContext });
  return Object.freeze(pinned);
}

/** Keep source authority and its guarded outbound callback on the server. */
async function draftSourceCheckpoint(req: DocumentDraftRequest) {
  const identity = Object.freeze({ organizationId: req.organizationId, userId: req.userId, projectId: req.projectId });
  const { assertDraftSourceContextCurrent, draftSourcePrompt, draftSourceAudit } = await import('./draft-project-sources.js');
  const assertCurrent = () => assertDraftSourceContextCurrent(req.sourceContext, identity);
  await assertCurrent();
  const selectedSources = req.sourceContext?.status === 'loaded';
  if (selectedSources && (req.onStream || req.enableTools)) throw new Error('SOURCE_CONTEXT_REQUIRES_NONSTREAMING_DRAFT');
  return { assertCurrent, prompt: draftSourcePrompt(req.sourceContext), audit: draftSourceAudit(req.sourceContext),
    dispatch: selectedSources ? { beforeDispatch: assertCurrent } : {} };
}

